# 方法一：DFS + 記憶化（推薦）
class Solution:
    def longestIncreasingPath(self, matrix: List[List[int]]) -> int:
        if not matrix or not matrix[0]:
            return 0

        m, n = len(matrix), len(matrix[0])
        memo = [[0] * n for _ in range(m)]
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        def dfs(i, j):
            # 已經計算過
            if memo[i][j] != 0:
                return memo[i][j]

            # 至少自己算一個長度
            max_length = 1

            # 探索四個方向
            for di, dj in directions:
                ni, nj = i + di, j + dj
                # 檢查邊界和遞增條件
                if 0 <= ni < m and 0 <= nj < n and matrix[ni][nj] > matrix[i][j]:
                    length = 1 + dfs(ni, nj)
                    max_length = max(max_length, length)

            memo[i][j] = max_length
            return max_length

        # 從每個點出發
        result = 0
        for i in range(m):
            for j in range(n):
                result = max(result, dfs(i, j))

        return result


# 方法二：拓撲排序（BFS）
class Solution:
    def longestIncreasingPath(self, matrix: List[List[int]]) -> int:
        if not matrix or not matrix[0]:
            return 0

        m, n = len(matrix), len(matrix[0])
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        # 計算出度
        out_degree = [[0] * n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                for di, dj in directions:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < m and 0 <= nj < n and matrix[ni][nj] > matrix[i][j]:
                        out_degree[i][j] += 1

        # 從出度為 0 的點開始（局部最大值）
        queue = deque()
        for i in range(m):
            for j in range(n):
                if out_degree[i][j] == 0:
                    queue.append((i, j))

        # BFS 逐層剝離
        length = 0
        while queue:
            length += 1
            size = len(queue)
            for _ in range(size):
                i, j = queue.popleft()
                for di, dj in directions:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < m and 0 <= nj < n and matrix[ni][nj] < matrix[i][j]:
                        out_degree[ni][nj] -= 1
                        if out_degree[ni][nj] == 0:
                            queue.append((ni, nj))

        return length


# 方法三：詳細註解版本
class Solution:
    def longestIncreasingPath(self, matrix: List[List[int]]) -> int:
        """
        DFS + 記憶化搜尋

        時間複雜度：O(m*n)，每個格子只訪問一次
        空間複雜度：O(m*n)，記憶化數組和遞迴棧
        """
        if not matrix or not matrix[0]:
            return 0

        m, n = len(matrix), len(matrix[0])
        # memo[i][j] 表示從 (i,j) 出發的最長路徑
        memo = [[0] * n for _ in range(m)]
        # 四個方向：上下左右
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        def dfs(i, j):
            """從 (i,j) 出發的最長遞增路徑長度"""
            # 記憶化：已經計算過了
            if memo[i][j] != 0:
                return memo[i][j]

            # 初始長度為 1（只有自己）
            max_length = 1

            # 嘗試四個方向
            for di, dj in directions:
                ni, nj = i + di, j + dj

                # 檢查邊界
                if not (0 <= ni < m and 0 <= nj < n):
                    continue

                # 檢查遞增條件
                if matrix[ni][nj] <= matrix[i][j]:
                    continue

                # 遞迴搜尋鄰居
                length = 1 + dfs(ni, nj)
                max_length = max(max_length, length)

            # 記憶化
            memo[i][j] = max_length
            return max_length

        # 從每個格子出發，找最大值
        result = 0
        for i in range(m):
            for j in range(n):
                result = max(result, dfs(i, j))

        return result


# 方法四：使用 @lru_cache 裝飾器
from functools import lru_cache

class Solution:
    def longestIncreasingPath(self, matrix: List[List[int]]) -> int:
        if not matrix or not matrix[0]:
            return 0

        m, n = len(matrix), len(matrix[0])
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        @lru_cache(None)
        def dfs(i, j):
            max_length = 1
            for di, dj in directions:
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n and matrix[ni][nj] > matrix[i][j]:
                    max_length = max(max_length, 1 + dfs(ni, nj))
            return max_length

        return max(dfs(i, j) for i in range(m) for j in range(n))

